import{_ as o,l,o as n,c as s,v as R,p as d,x as t,d as r,i as p,S,b as a}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"已实现半方差与符号跳跃","description":"","frontmatter":{"title":"已实现半方差与符号跳跃","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/realized-semivariance.md","filePath":"quant/realized-semivariance.md","lastUpdated":1789023840000}'),E={name:"quant/realized-semivariance.md"};function h(B,e,A,c,u,m){const i=l("Mermaid");return n(),s("div",null,[e[1]||(e[1]=R('<h1 id="已实现半方差与符号跳跃" tabindex="-1">已实现半方差与符号跳跃 <a class="header-anchor" href="#已实现半方差与符号跳跃" aria-label="Permalink to &quot;已实现半方差与符号跳跃&quot;">​</a></h1><div class="epigraph"><p>把已实现方差拆成正收益平方和与负收益平方和，下行部分往往更持续、对未来方差更有预报力；符号跳跃是两边之差，不是再做一次无符号的跳跃检验。</p><footer>—— Barndorff-Nielsen, Kinnebrock and Shephard, Measuring Downside Risk: Realised Semivariance, 2010 前后工作；预报力见 Patton and Sheppard, Journal of Financial Econometrics, 2015</footer></div><p><a href="/quant/intraday-seasonality">日内季节性</a> 之后，格子收益可当作更齐次的输入。<a href="/quant/rv-noise">已实现方差</a> 把所有 \\(r_i^2\\) 加总；<a href="/quant/jump-tests">跳跃检验</a> 用双幂次分离连续与跳，仍无符号。Barndorff-Nielsen、Kinnebrock 与 Shephard 的已实现半方差</p> \\[RS^-=\\sum_i r_i^2 1_{r_i\\lt 0},\\qquad RS^+=\\sum_i r_i^2 1_{r_i\\gt 0}, \\]<p>在无跳时各趋于 \\(IV/2\\)，有跳时把跳的平方记入对应符号。Patton–Sheppard 表明 \\(RS^-\\) 对未来 RV 的预测强于 \\(RS^+\\)。本课是「多元与长记忆」的收束：对象从对称长记忆转到<strong>非对称二阶</strong>。下一单元噪声下的估计从预平均开始，半方差同样会被噪声污染，须把测量问题单独开课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>杠杆效应：跌时波动升。EGARCH/GJR 在日频用符号乘平方；高频用 \\(RS^\\pm\\) 直接测量当天下行二次变差。问题是构造一致估计、处理噪声与隔夜，以及在 HAR 里用 \\(RS^-\\) 替换或并列 \\(RV\\)（HAR-RS）。符号跳跃 \\(SJ=RS^+-RS^-\\) 接近「当天跳的方向性贡献」，与 BN–S 的无符号跳份额不同。</p><p>对象：下行风险、预测、以及是否把负跳当状态变量。不是再推导双幂次。</p><h3 id="无跳极限与有跳" tabindex="-1">无跳极限与有跳 <a class="header-anchor" href="#无跳极限与有跳" aria-label="Permalink to &quot;无跳极限与有跳&quot;">​</a></h3><p>连续对称半鞅，\\(RS^\\pm\\to_p IV/2\\)。有限活动跳把 \\((\\Delta X)^2\\) 放入对应半方差。因此 \\(RS^-\\) 既含连续一半也含负跳。若只要连续下行，需半幂次或先去跳再拆符号，理论更重。实务 HAR-RS 常用朴素 \\(RS^-\\)，接受混合对象，因为它预报好。</p><p><span class="marginnote">隔夜负收益很大时，若不算进 \\(RS^-\\)，当天「下行」被低估。是否并入隔夜应与 RV 定义一致，并在季节课的隔夜项上对齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>构造。</strong> 同一网格上对 \\(r_i\\) 按符号分流平方和。噪声使 \\(r_i\\) 弹跳变号，密采样 \\(RS^\\pm\\) 被噪声主导且符号不可靠——应先降频、预平均或核，再拆符号。下一单元会把预平均、TSRV 讲透；本课只要求：半方差继承 RV 的带宽纪律。</p><p><strong>预测。</strong> Patton–Sheppard：\\(RV_{t+1}\\) 对 \\(RS^-_t\\)、\\(RS^+_t\\) 回归，\\(RS^-\\) 系数显著更大。QLIKE 评估，接上一课。可加杠杆项与 HAR 的周月 \\(RS^-\\)。</p><p><strong>检验。</strong> \\(RS^+\\) 与 \\(RS^-\\) 是否同分布、符号跳是否与新闻同向，描述性即可；正式跳仍用 BN–S/Lee–Mykland，再给跳标符号。不要用 \\(SJ\\) 替代 \\(Z_J\\)。</p><h3 id="与-egarch-的分工" tabindex="-1">与 EGARCH 的分工 <a class="header-anchor" href="#与-egarch-的分工" aria-label="Permalink to &quot;与 EGARCH 的分工&quot;">​</a></h3><p>日频 GJR 用一个平方和一个符号，信息少。\\(RS^-\\) 用日内格子，信息多。有高频时 HAR-RS 通常打赢 GJR 的一日前预测。无高频时 GJR 仍是默认非对称。不要对日收益硬造「半方差」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续部分对称时，正负格的二次贡献各半；杠杆来自 \\(\\sigma\\) 对负冲击的反馈，出现在<strong>下一期</strong>的 IV，而不是要求当天 \\(RS^-\\gt RS^+\\)。当天 \\(RS^-\\) 更大，往往是因为当天已经有负跳或单边跌。预报力机制：下行已实现把「坏的波动状态」测得更准，状态持续，故预测未来 RV。上行平方更多是噪声或短暂挤空，持续弱。</p><p>与负半方差风险（资产定价）：截面上对 \\(RS^-\\) 载荷要溢价，是另一组 FM 检验，本课不展开。计量对象先测准 \\(RS^-\\)。</p><p><span class="marginnote">开盘未除季节时，\\(RS^-\\) 会被开盘下跳主导。先季节后半方差，与上一课交接一致。</span></p><h3 id="到高频单元的交接" tabindex="-1">到高频单元的交接 <a class="header-anchor" href="#到高频单元的交接" aria-label="Permalink to &quot;到高频单元的交接&quot;">​</a></h3><p>半方差、RV、协方差，在噪声下都不一致。下一单元第一课 <a href="/quant/pre-averaging">预平均</a> 从测量端修 \\(Y=X+\\varepsilon\\)，半方差同样可预平均后再拆符号。本单元不再把噪声当主对象。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>买卖弹跳让中点收益的符号比成交价干净，但中点不是可交易路径。极薄股票大量零收益格，\\(RS^\\pm\\) 稀疏。多元下行协方差（负半协变差）对异步更脆弱，留给已实现协方差课。</p><p>工程：日 RV 预测默认加 \\(RS^-\\)；网格与噪声处理与 RV 相同；QLIKE 评估。不要用 \\(RS^-\\) 当 VaR——分位是另一泛函。不要把符号跳当可交易预测器而不做样本外。高频单元开始后，所有已实现量默认要过噪声这一关。</p>',26)),(n(),d(S,null,{default:t(()=>[p(i,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%BC%E5%AD%90%E6%94%B6%E7%9B%8A%20r_i%22%5D%20--%3E%20RV%5B%22RV%20%3D%20%CE%A3%20r%C2%B2%22%5D%0A%20%20R%20--%3E%20RS%5B%22RS%E2%81%BB%20%2F%20RS%E2%81%BA%20%E6%8C%89%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20RS%20--%3E%20HAR%5B%22HAR-RS%20%E9%A2%84%E6%B5%8B%22%5D%0A%20%20RV%20--%3E%20J%5B%22BN-S%20%E6%97%A0%E7%AC%A6%E5%8F%B7%E8%B7%B3%22%5D%0A%20%20RS%20--%3E%20SJ%5B%22%E7%AC%A6%E5%8F%B7%E8%B7%B3%20RS%E2%81%BA%20%E2%88%92%20RS%E2%81%BB%22%5D%0A%20%20N%5B%22%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20BIAS%5B%22%E5%AF%86%E9%87%87%E6%A0%B7%E7%AC%A6%E5%8F%B7%E4%B8%8D%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20BIAS%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E5%8D%95%E5%85%83%3A%20%E9%A2%84%E5%B9%B3%E5%9D%87%20%2F%20TSRV%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[r("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"已实现半方差按格收益符号拆开二次变差；无跳时各趋 \\(IV/2\\)，有跳则带符号。"),a("li",null,"\\(RS^-\\) 对未来 RV 往往更有预报力，HAR-RS 是自然扩展；用 QLIKE 评估。"),a("li",null,"符号跳不是 BN–S 的替代；噪声与季节须先处理再拆符号。"),a("li",null,"与 GJR 分工：有高频用半方差，无高频用日频杠杆项。"),a("li",null,[r("出处：Barndorff-Nielsen, Kinnebrock and Shephard 论已实现半方差；Patton and Sheppard, "),a("em",null,"Journal of Financial Econometrics"),r(", 2015；Andersen 等已实现波动传统。")])],-1))])}const q=o(E,[["render",h]]);export{f as __pageData,q as default};
